                                {action.shortcut}
                              </kbd>
                            )}
                          </div>
                        </motion.li>
                      ))}
                    </ul>
                  </motion.div>
                )}

                {/* Suggested actions */}
                {searchResults.suggestedActions.length > 0 && (
                  <motion.div variants={itemVariants}>
                    <div className="px-3 pt-2 pb-1">
                      <h3 className="text-xs font-medium text-muted-foreground">Suggested</h3>
