}

const FILE_TYPE_CONFIG = {
  image: {
    icon: ImageIcon,
    bg: "bg-violet-500/10 dark:bg-violet-500/10",
    text: "text-violet-500",
    border: "border-violet-200 dark:border-violet-500/20",
