"use client";

import { useState } from "react";
import { Info, ChevronDown, ChevronUp, X } from "lucide-react";
import { cn } from "@/lib/utils";

interface StackedItem {
  id: string;
  title: string;
  message: string;
  time: string;
}

interface Alert06Props {
  items?: StackedItem[];
  onDismiss?: (id: string) => void;
  onDismissAll?: () => void;
  className?: string;
}

const defaultItems: StackedItem[] = [
  {
    id: "1",
    title: "System update available",
    message: "A new version is ready to install.",
    time: "2m ago",
  },
  {
    id: "2",
    title: "Backup completed",
    message: "Your data has been backed up successfully.",
    time: "5m ago",
  },
  {
    id: "3",
    title: "New comment",
    message: "Someone commented on your post.",
    time: "12m ago",
  },
];

export default function Alert06({
  items = defaultItems,
  onDismiss,
  onDismissAll,
  className,
}: Alert06Props) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [visibleItems, setVisibleItems] = useState<StackedItem[]>(items);
  const [exitingId, setExitingId] = useState<string | null>(null);

  const handleDismissItem = (id: string) => {
    setExitingId(id);
    setTimeout(() => {
      setVisibleItems((prev) => prev.filter((item) => item.id !== id));
      setExitingId(null);
      onDismiss?.(id);
    }, 200);
  };

  const handleDismissAll = () => {
    setVisibleItems([]);
    onDismissAll?.();
  };

  if (visibleItems.length === 0) return null;

  const displayedItems = isExpanded ? visibleItems : visibleItems.slice(0, 1);

  return (
    <div className={cn("w-full max-w-md mx-auto", className)}>
      <div className="space-y-2">
        {displayedItems.map((item, index) => (
          <div
            key={item.id}
            className={cn(
              "relative rounded-xl overflow-hidden",
              "bg-white dark:bg-zinc-900",
              "border border-zinc-200 dark:border-zinc-800",
              "shadow-sm",
              "transition-all duration-200",
              exitingId === item.id && "opacity-0 scale-95 -translate-x-4",
              !isExpanded && index > 0 && "hidden",
            )}
            style={{
              zIndex: visibleItems.length - index,
            }}
            role="alert"
          >
            <div className="p-4">
              <div className="flex items-start gap-3">
                <div className="flex-shrink-0 mt-0.5">
                  <div className="p-1.5 rounded-lg bg-blue-100 dark:bg-blue-950/50">
                    <Info className="h-4 w-4 text-blue-600 dark:text-blue-400" />
                  </div>
                </div>

                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between gap-2">
                    <h3 className="text-sm font-medium text-zinc-900 dark:text-zinc-100 truncate">
                      {item.title}
                    </h3>
                    <span className="flex-shrink-0 text-[11px] text-zinc-400 dark:text-zinc-500">
                      {item.time}
                    </span>
                  </div>
                  <p className="mt-0.5 text-[13px] text-zinc-600 dark:text-zinc-400 truncate">
                    {item.message}
                  </p>
                </div>

                <button
                  onClick={() => handleDismissItem(item.id)}
                  className={cn(
                    "flex-shrink-0 p-1 rounded-md",
                    "text-zinc-400 hover:text-zinc-600 dark:text-zinc-500 dark:hover:text-zinc-300",
                    "hover:bg-zinc-100 dark:hover:bg-zinc-800",
                    "transition-colors duration-150",
                    "focus:outline-none focus:ring-2 focus:ring-blue-400",
                  )}
                  aria-label="Dismiss"
                >
                  <X className="h-3.5 w-3.5" />
                </button>
              </div>
            </div>
          </div>
        ))}

        {visibleItems.length > 1 && (
          <div className="flex items-center justify-between pt-1">
            <button
              onClick={() => setIsExpanded(!isExpanded)}
              className={cn(
                "inline-flex items-center gap-1 px-2 py-1 text-xs font-medium rounded-md",
                "text-zinc-600 dark:text-zinc-400",
                "hover:bg-zinc-100 dark:hover:bg-zinc-800",
                "transition-colors duration-150",
                "focus:outline-none focus:ring-2 focus:ring-blue-400",
              )}
            >
              {isExpanded ? (
                <>
                  <ChevronUp className="h-3.5 w-3.5" />
                  Show less
                </>
              ) : (
                <>
                  <ChevronDown className="h-3.5 w-3.5" />
                  {visibleItems.length - 1} more notification{visibleItems.length > 2 ? "s" : ""}
                </>
              )}
            </button>

            <button
              onClick={handleDismissAll}
              className={cn(
                "px-2 py-1 text-xs font-medium rounded-md",
                "text-zinc-500 hover:text-zinc-700 dark:text-zinc-500 dark:hover:text-zinc-300",
                "hover:bg-zinc-100 dark:hover:bg-zinc-800",
                "transition-colors duration-150",
                "focus:outline-none focus:ring-2 focus:ring-blue-400",
              )}
            >
              Clear all
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Settings, X, ToggleLeft, ToggleRight } from "lucide-react";
import { cn } from "@/lib/utils";

interface SettingOption {
  id: string;
  label: string;
  description: string;
  enabled: boolean;
}

interface Alert07Props {
  title?: string;
  options?: SettingOption[];
  onSave?: (options: SettingOption[]) => void;
  onDismiss?: () => void;
  className?: string;
}

const defaultOptions: SettingOption[] = [
  {
    id: "notifications",
    label: "Push notifications",
    description: "Receive alerts on your device",
    enabled: true,
  },
  {
    id: "sounds",
    label: "Sound effects",
    description: "Play sounds for interactions",
    enabled: false,
  },
];

export default function Alert07({
  title = "Quick Settings",
  options = defaultOptions,
  onSave,
  onDismiss,
  className,
}: Alert07Props) {
  const [isVisible, setIsVisible] = useState(true);
  const [isExiting, setIsExiting] = useState(false);
  const [settings, setSettings] = useState<SettingOption[]>(options);
  const [isSaving, setIsSaving] = useState(false);

  const handleDismiss = () => {
    setIsExiting(true);
    setTimeout(() => {
      setIsVisible(false);
      onDismiss?.();
    }, 200);
  };

  const handleToggle = (id: string) => {
    setSettings((prev) =>
      prev.map((option) => (option.id === id ? { ...option, enabled: !option.enabled } : option)),
    );
  };

  const handleSave = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      onSave?.(settings);
      handleDismiss();
    }, 500);
  };

  if (!isVisible) return null;

  return (
    <div className={cn("w-full max-w-sm mx-auto", className)}>
      <div
        className={cn(
          "relative rounded-xl overflow-hidden",
          "bg-white dark:bg-zinc-900",
          "border border-zinc-200 dark:border-zinc-800",
          "shadow-lg shadow-zinc-200/50 dark:shadow-zinc-950/50",
          "transition-all duration-200",
          isExiting && "opacity-0 scale-95",
        )}
        role="dialog"
        aria-labelledby="settings-title"
      >
        <div className="flex items-center justify-between px-4 py-3 border-b border-zinc-100 dark:border-zinc-800">
          <div className="flex items-center gap-2">
            <Settings className="h-4 w-4 text-zinc-500 dark:text-zinc-400" />
            <h3
              id="settings-title"
              className="text-sm font-semibold text-zinc-900 dark:text-zinc-100"
            >
              {title}
            </h3>
          </div>
          <button
            onClick={handleDismiss}
            className={cn(
              "p-1 rounded-md",
              "text-zinc-400 hover:text-zinc-600 dark:text-zinc-500 dark:hover:text-zinc-300",
              "hover:bg-zinc-100 dark:hover:bg-zinc-800",
              "transition-colors duration-150",
              "focus:outline-none focus:ring-2 focus:ring-zinc-400",
            )}
            aria-label="Close"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        <div className="p-4 space-y-3">
          {settings.map((option) => (
            <div key={option.id} className="flex items-center justify-between gap-4">
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-zinc-900 dark:text-zinc-100">
                  {option.label}
                </p>
                <p className="text-xs text-zinc-500 dark:text-zinc-400">{option.description}</p>
              </div>
              <button
                onClick={() => handleToggle(option.id)}
                className={cn(
                  "flex-shrink-0 relative p-0.5 rounded-full w-10 h-6",
                  "transition-colors duration-200",
                  "focus:outline-none focus:ring-2 focus:ring-blue-400 focus:ring-offset-2",
                  "dark:focus:ring-offset-zinc-900",
                  option.enabled ? "bg-blue-600" : "bg-zinc-200 dark:bg-zinc-700",
                )}
                role="switch"
                aria-checked={option.enabled}
                aria-label={option.label}
              >
                <span
                  className={cn(
                    "block w-5 h-5 rounded-full bg-white shadow-sm",
                    "transition-transform duration-200",
                    option.enabled ? "translate-x-4" : "translate-x-0",
                  )}
                />
              </button>
            </div>
          ))}
        </div>

        <div className="px-4 py-3 bg-zinc-50 dark:bg-zinc-800/50 border-t border-zinc-100 dark:border-zinc-800">
          <div className="flex justify-end gap-2">
            <button
              onClick={handleDismiss}
              className={cn(
                "px-3 py-1.5 text-xs font-medium rounded-lg",
                "text-zinc-600 dark:text-zinc-400",
                "hover:bg-zinc-100 dark:hover:bg-zinc-700",
                "transition-colors duration-150",
                "focus:outline-none focus:ring-2 focus:ring-zinc-400",
              )}
            >
              Cancel
            </button>
            <button
              onClick={handleSave}
              disabled={isSaving}
              className={cn(
                "px-3 py-1.5 text-xs font-medium rounded-lg",
                "bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900",
                "hover:bg-zinc-800 dark:hover:bg-zinc-200",
                "transition-colors duration-150",
                "disabled:opacity-50",
                "focus:outline-none focus:ring-2 focus:ring-zinc-400 focus:ring-offset-2",
                "dark:focus:ring-offset-zinc-900",
              )}
            >
              {isSaving ? "Saving..." : "Save changes"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useRef, useEffect } from "react";
import { Command, Search, ArrowRight, X } from "lucide-react";
import { cn } from "@/lib/utils";

interface CommandOption {
  id: string;
  label: string;
  shortcut?: string;
  icon?: React.ReactNode;
}

interface Alert08Props {
  placeholder?: string;
  options?: CommandOption[];
  onSelect?: (option: CommandOption) => void;
  onDismiss?: () => void;
  className?: string;
}

const defaultOptions: CommandOption[] = [
  { id: "search", label: "Search documentation", shortcut: "⌘K" },
  { id: "new", label: "Create new project", shortcut: "⌘N" },
  { id: "settings", label: "Open settings", shortcut: "⌘," },
  { id: "theme", label: "Toggle theme", shortcut: "⌘T" },
];

export default function Alert08({
  placeholder = "Type a command or search...",
  options = defaultOptions,
  onSelect,
  onDismiss,
  className,
}: Alert08Props) {
  const [isVisible, setIsVisible] = useState(true);
  const [isExiting, setIsExiting] = useState(false);
  const [query, setQuery] = useState("");
  const [selectedIndex, setSelectedIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);

  const filteredOptions = options.filter((option) =>
    option.label.toLowerCase().includes(query.toLowerCase()),
  );

  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  useEffect(() => {
    setSelectedIndex(0);
  }, [query]);

  const handleDismiss = () => {
    setIsExiting(true);
    setTimeout(() => {
      setIsVisible(false);
      onDismiss?.();
    }, 150);
  };

  const handleSelect = (option: CommandOption) => {
    onSelect?.(option);
    handleDismiss();
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        setSelectedIndex((prev) => (prev < filteredOptions.length - 1 ? prev + 1 : prev));
        break;
      case "ArrowUp":
        e.preventDefault();
        setSelectedIndex((prev) => (prev > 0 ? prev - 1 : prev));
        break;
      case "Enter":
        e.preventDefault();
        if (filteredOptions[selectedIndex]) {
          handleSelect(filteredOptions[selectedIndex]);
        }
        break;
      case "Escape":
        e.preventDefault();
        handleDismiss();
        break;
    }
  };

  if (!isVisible) return null;

  return (
    <div className={cn("w-full max-w-lg mx-auto", className)}>
      <div
        className={cn(
          "relative rounded-xl overflow-hidden",
          "bg-white dark:bg-zinc-900",
          "border border-zinc-200 dark:border-zinc-800",
          "shadow-2xl shadow-zinc-300/50 dark:shadow-zinc-950/50",
          "transition-all duration-150",
          isExiting && "opacity-0 scale-95",
        )}
        role="dialog"
        aria-label="Command palette"
      >
        <div className="flex items-center gap-3 px-4 py-3 border-b border-zinc-100 dark:border-zinc-800">
          <Search className="h-4 w-4 text-zinc-400 dark:text-zinc-500 flex-shrink-0" />
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            className={cn(
              "flex-1 bg-transparent text-sm",
              "text-zinc-900 dark:text-zinc-100",
              "placeholder:text-zinc-400 dark:placeholder:text-zinc-500",
              "focus:outline-none",
            )}
          />
          <div className="flex items-center gap-1.5">
            <kbd className="px-1.5 py-0.5 text-[10px] font-medium rounded bg-zinc-100 dark:bg-zinc-800 text-zinc-500 dark:text-zinc-400 border border-zinc-200 dark:border-zinc-700">
              ESC
            </kbd>
          </div>
        </div>

        <div className="max-h-64 overflow-y-auto py-2">
          {filteredOptions.length === 0 ? (
            <div className="px-4 py-8 text-center">
              <p className="text-sm text-zinc-500 dark:text-zinc-400">
                No results found for &ldquo;{query}&rdquo;
              </p>
            </div>
          ) : (
            <div role="listbox">
              {filteredOptions.map((option, index) => (
                <button
                  key={option.id}
                  onClick={() => handleSelect(option)}
                  onMouseEnter={() => setSelectedIndex(index)}
                  className={cn(
                    "w-full flex items-center justify-between gap-3 px-4 py-2.5",
                    "text-left transition-colors duration-75",
                    "focus:outline-none",
                    index === selectedIndex
                      ? "bg-zinc-100 dark:bg-zinc-800"
                      : "hover:bg-zinc-50 dark:hover:bg-zinc-800/50",
                  )}
                  role="option"
                  aria-selected={index === selectedIndex}
                >
                  <div className="flex items-center gap-3">
                    <div className="p-1.5 rounded-md bg-zinc-100 dark:bg-zinc-800">
                      <Command className="h-3.5 w-3.5 text-zinc-500 dark:text-zinc-400" />
                    </div>
                    <span className="text-sm text-zinc-700 dark:text-zinc-300">{option.label}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    {option.shortcut && (
                      <kbd className="px-1.5 py-0.5 text-[10px] font-medium rounded bg-zinc-100 dark:bg-zinc-800 text-zinc-400 dark:text-zinc-500">
                        {option.shortcut}
                      </kbd>
                    )}
                    {index === selectedIndex && (
                      <ArrowRight className="h-3.5 w-3.5 text-zinc-400 dark:text-zinc-500" />
                    )}
                  </div>
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="px-4 py-2.5 bg-zinc-50 dark:bg-zinc-800/50 border-t border-zinc-100 dark:border-zinc-800">
          <div className="flex items-center justify-between text-[11px] text-zinc-500 dark:text-zinc-400">
            <div className="flex items-center gap-3">
              <span className="flex items-center gap-1">
                <kbd className="px-1 py-0.5 rounded bg-zinc-200 dark:bg-zinc-700 text-[10px]">
                  ↑
                </kbd>
                <kbd className="px-1 py-0.5 rounded bg-zinc-200 dark:bg-zinc-700 text-[10px]">
                  ↓
                </kbd>
                to navigate
              </span>
              <span className="flex items-center gap-1">
                <kbd className="px-1 py-0.5 rounded bg-zinc-200 dark:bg-zinc-700 text-[10px]">
                  ↵
                </kbd>
                to select
              </span>
            </div>
            <span>{filteredOptions.length} commands</span>
          </div>
        </div>
      </div>
    </div>
  );
}

