export function useTags({
  onChange,
  defaultTags = [],
  maxTags = 10,
  defaultColors = [
    "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300",
    "bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-300",
    "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300",
    "bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-300",
    "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300",
  ],
}: UseTagsProps = {}) {
  const [tags, setTags] = useState<Tag[]>(defaultTags);

  function addTag(tag: Tag) {
    if (tags.length >= maxTags) return;

    const newTags = [
      ...tags,
      {
        ...tag,
        color: tag.color || defaultColors[tags.length % defaultColors.length],
      },
    ];
    setTags(newTags);
    onChange?.(newTags);
    return newTags;
  }

  function removeTag(tagId: string) {
    const newTags = tags.filter((t) => t.id !== tagId);
    setTags(newTags);
    onChange?.(newTags);
    return newTags;
  }

  function removeLastTag() {
    if (tags.length === 0) return;
    return removeTag(tags[tags.length - 1].id);
  }

  return {
    tags,
    setTags,
    addTag,
    removeTag,
    removeLastTag,
    hasReachedMax: tags.length >= maxTags,
  };
}

import { useEffect, type RefObject } from "react";

export function useClickOutside(ref: RefObject<HTMLElement>, handler: () => void) {
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (ref.current && !ref.current.contains(event.target as Node)) {
        handler();
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [ref, handler]);
}

"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";
import { Upload, X, FileText } from "lucide-react";
import { useFileInput } from "@/hooks/use-file-input";

export default function Input_03() {
  const [isDragging, setIsDragging] = useState(false);
  const [preview, setPreview] = useState<string | null>(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const { fileName, fileInputRef, clearFile, error, validateAndSetFile, fileSize } = useFileInput({
    accept: "image/*",
    maxSize: 5,
  });

  function handleFile(file: File) {
    validateAndSetFile(file);

    if (!error) {
      simulateUpload(file);
    }
  }

  function simulateUpload(file: File) {
    let progress = 0;
    const interval = setInterval(() => {
      progress += 10;
      setUploadProgress(progress);
      if (progress >= 100) {
        clearInterval(interval);
        if (file.type.startsWith("image/")) {
          const reader = new FileReader();
          reader.onloadend = () => {
            setPreview(reader.result as string);
          };
          reader.readAsDataURL(file);
        }
      }
    }, 100);
  }

  function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    setIsDragging(false);

    const droppedFile = e.dataTransfer.files[0];
    if (!droppedFile) return;

    handleFile(droppedFile);
  }

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    handleFile(selectedFile);
  }

  function removeFile() {
    clearFile();
    setPreview(null);
    setUploadProgress(0);
  }

  return (
    <div className="w-full max-w-md space-y-2">
      <label className="text-sm font-medium text-zinc-700 dark:text-zinc-300">Upload file</label>
      <div
        className={cn(
          "relative group cursor-pointer",
          "rounded-lg border-2 border-dashed",
          "transition-colors duration-200",
          isDragging
            ? "border-indigo-500 bg-indigo-50/50 dark:bg-indigo-500/10"
            : "border-zinc-200 dark:border-zinc-800",
        )}
        onDragOver={(e) => {
          e.preventDefault();
          setIsDragging(true);
        }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            fileInputRef.current?.click();
          }
        }}
        aria-label="Upload file"
      >
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          onChange={handleChange}
          className="hidden"
        />

        <div className="p-8 space-y-4">
          {!fileName ? (
            <div className="flex flex-col items-center gap-2">
              <Upload className="w-8 h-8 text-zinc-400 dark:text-zinc-500" />
              <p className="text-sm text-zinc-600 dark:text-zinc-400">
                Drag and drop or click to upload
              </p>
            </div>
          ) : (
            <div className="flex items-center gap-4">
              {preview ? (
                <div className="relative w-16 h-16 rounded-lg overflow-hidden">
                  <img src={preview} alt="Preview" className="w-full h-full object-cover" />
                </div>
              ) : (
                <div className="w-16 h-16 rounded-lg bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center">
                  <FileText className="w-8 h-8 text-zinc-400" />
                </div>
              )}
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium truncate">{fileName || "No file selected"}</p>
                <p className="text-xs text-zinc-500">
                  {fileSize ? `${(fileSize / 1024 / 1024).toFixed(2)} MB` : "0 MB"}
                </p>
                {uploadProgress < 100 && (
                  <div className="mt-2 h-1 w-full bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-indigo-500 transition-all duration-200"
                      style={{
                        width: `${uploadProgress}%`,
                      }}
                    />
                  </div>
                )}
              </div>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  removeFile();
                }}
                className="p-1 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded"
              >
                <X className="w-5 h-5 text-zinc-400" />
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useRef, useState } from "react";

interface UseFileInputOptions {
  accept?: string;
  /** Max size in megabytes */
  maxSize?: number;
}

export function useFileInput({ accept = "*", maxSize = 10 }: UseFileInputOptions = {}) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [fileName, setFileName] = useState<string | null>(null);
  const [fileSize, setFileSize] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);

  const clearFile = useCallback(() => {
    setFileName(null);
    setFileSize(0);
    setError(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  }, []);

  const validateAndSetFile = useCallback(
    (file: File) => {
      setError(null);

      if (accept !== "*" && accept !== "image/*") {
        const types = accept.split(",").map((t) => t.trim());
        if (
          !types.some(
            (t) => file.type === t || file.name.toLowerCase().endsWith(t.replace(".", "")),
          )
        ) {
          setError(`File type not accepted. Expected: ${accept}`);
          return;
        }
      } else if (accept === "image/*" && !file.type.startsWith("image/")) {
        setError("Please select an image file.");
        return;
      }

      const maxBytes = maxSize * 1024 * 1024;
      if (file.size > maxBytes) {
        setError(`File must be smaller than ${maxSize} MB.`);
        return;
      }

      setFileName(file.name);
      setFileSize(file.size);
    },
    [accept, maxSize],
  );

  return {
    fileName,
    fileInputRef,
    clearFile,
    error,
    validateAndSetFile,
    fileSize,
  };
}

