"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import { cn } from "@/lib/utils";

const OTP_LENGTH = 6;

export default function Input_06() {
  const [code, setCode] = useState<string[]>(Array(OTP_LENGTH).fill(""));
  const [activeIndex, setActiveIndex] = useState(0);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);
  const [shake, setShake] = useState(false);

  useEffect(() => {
    inputRefs.current = inputRefs.current.slice(0, OTP_LENGTH);
  }, []);

  const handleChange = (index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;

    const newCode = [...code];
    newCode[index] = value.slice(-1);
    setCode(newCode);

    if (value && index < OTP_LENGTH - 1) {
      inputRefs.current[index + 1]?.focus();
      setActiveIndex(index + 1);
    }
  };

  const handleKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Backspace" && !code[index] && index > 0) {
      // Move to previous input on backspace if current input is empty
      inputRefs.current[index - 1]?.focus();
      setActiveIndex(index - 1);
    } else if (e.key === "ArrowLeft" && index > 0) {
      inputRefs.current[index - 1]?.focus();
      setActiveIndex(index - 1);
    } else if (e.key === "ArrowRight" && index < OTP_LENGTH - 1) {
      inputRefs.current[index + 1]?.focus();
      setActiveIndex(index + 1);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    e.preventDefault();
    const pastedData = e.clipboardData.getData("text/plain").slice(0, OTP_LENGTH);

    if (!/^\d+$/.test(pastedData)) {
      setShake(true);
      setTimeout(() => setShake(false), 600);
      return;
    }

    const newCode = [...code];
    pastedData.split("").forEach((digit, index) => {
      newCode[index] = digit;
    });
    setCode(newCode);

    const focusIndex = Math.min(pastedData.length, OTP_LENGTH - 1);
    inputRefs.current[focusIndex]?.focus();
    setActiveIndex(focusIndex);
  };

  const setInputRef = useCallback(
    (index: number) => (el: HTMLInputElement | null) => {
      inputRefs.current[index] = el;
    },
    [],
  );

  return (
    <div className="w-full max-w-sm space-y-2">
      <fieldset className={cn("flex flex-col gap-2", shake && "animate-shake")}>
        <legend className="text-sm font-medium text-zinc-700 dark:text-zinc-300 mb-2">
          Verification Code
        </legend>

        <div className="flex gap-2 items-center justify-start">
          {Array.from({ length: OTP_LENGTH }).map((_, index) => (
            <div key={`otp-input-${index}`} className="relative">
              <input
                id={`otp-input-${index}`}
                ref={setInputRef(index)}
                type="text"
                inputMode="numeric"
                maxLength={1}
                value={code[index]}
                onChange={(e) => handleChange(index, e.target.value)}
                onKeyDown={(e) => handleKeyDown(index, e)}
                onPaste={handlePaste}
                onFocus={() => setActiveIndex(index)}
                className={cn(
                  "w-12 h-14 text-center text-lg font-semibold",
                  "rounded-lg border",
                  "transition-all duration-200",
                  "bg-white dark:bg-zinc-900",
                  "border-zinc-200 dark:border-zinc-800",
                  activeIndex === index && "border-indigo-500 dark:border-indigo-500",
                  "focus:outline-hidden focus:ring-2",
                  "focus:ring-indigo-500/20",
                )}
                suppressHydrationWarning
              />
              {index !== 6 - 1 && (
                <div className="absolute top-1/2 -right-2 w-2 transform -translate-y-1/2">
                  <div className="w-1 h-1 rounded-full bg-zinc-300 dark:bg-zinc-600" />
                </div>
              )}
            </div>
          ))}
        </div>
      </fieldset>
    </div>
  );
}

"use client";

import React, { useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { ShieldCheck } from "lucide-react";

interface Input07Props {
  length?: number;
  onComplete?: (otp: string) => void;
  error?: boolean;
}

export default function Input_07({ length = 6, onComplete, error = false }: Input07Props) {
  const [values, setValues] = useState<string[]>(Array(length).fill(""));
  const [shake, setShake] = useState(false);
  const inputsRef = useRef<(HTMLInputElement | null)[]>([]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>, index: number) => {
    const val = e.target.value;
    const lastChar = val.substring(val.length - 1);

    // Only allow numbers
    if (lastChar && !/^\d+$/.test(lastChar)) return;

    const newValues = [...values];
    newValues[index] = lastChar;
    setValues(newValues);

    // Auto-focus next field
    if (lastChar !== "" && index < length - 1) {
      inputsRef.current[index + 1]?.focus();
    }

    // Trigger onComplete when all fields are filled
    const completeCode = newValues.join("");
    if (completeCode.length === length && onComplete) {
      onComplete(completeCode);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, index: number) => {
    if (e.key === "Backspace") {
      if (values[index] === "" && index > 0) {
        // Move focus back
        inputsRef.current[index - 1]?.focus();
        const newValues = [...values];
        newValues[index - 1] = "";
        setValues(newValues);
      } else {
        const newValues = [...values];
        newValues[index] = "";
        setValues(newValues);
      }
    } else if (e.key === "ArrowLeft" && index > 0) {
      inputsRef.current[index - 1]?.focus();
    } else if (e.key === "ArrowRight" && index < length - 1) {
      inputsRef.current[index + 1]?.focus();
    }
  };

  const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
    e.preventDefault();
    const pastedText = e.clipboardData.getData("text").trim();
    if (!/^\d+$/.test(pastedText)) return;

    const codeChars = pastedText.split("").slice(0, length);
    const newValues = [...values];

    codeChars.forEach((char, idx) => {
      newValues[idx] = char;
      if (inputsRef.current[idx]) {
        inputsRef.current[idx]!.value = char;
      }
    });

    setValues(newValues);

    // Focus the last filled box or the final box
    const focusIndex = Math.min(codeChars.length, length - 1);
    inputsRef.current[focusIndex]?.focus();

    const completeCode = newValues.join("");
    if (completeCode.length === length && onComplete) {
      onComplete(completeCode);
    }
  };

  const triggerErrorShake = () => {
    setShake(true);
    setTimeout(() => setShake(false), 500);
  };

  return (
    <div className="w-full max-w-sm p-6 rounded-3xl border border-zinc-200/60 dark:border-zinc-800 bg-white dark:bg-zinc-950 shadow-xs">
      <div className="flex flex-col items-center text-center mb-6">
        <div className="w-10 h-10 rounded-xl bg-zinc-100 dark:bg-zinc-900 flex items-center justify-center text-zinc-700 dark:text-zinc-300 mb-3 border border-zinc-200 dark:border-zinc-800">
          <ShieldCheck className="w-5 h-5" />
        </div>
        <h3 className="text-base font-bold text-zinc-950 dark:text-zinc-50 tracking-tight">
          Security Verification
        </h3>
        <p className="text-xs text-zinc-500 dark:text-zinc-400 mt-1">
          Enter the {length}-digit code sent to your email.
        </p>
      </div>

      <div
        className={cn(
          "flex justify-center gap-2",
          shake && "animate-bounce", // Fallback shake/bounce effect
        )}
      >
        {values.map((val, index) => (
          <input
            key={index}
            type="text"
            inputMode="numeric"
            pattern="[0-9]*"
            maxLength={1}
            value={val}
            ref={(el) => {
              inputsRef.current[index] = el;
            }}
            onChange={(e) => handleChange(e, index)}
            onKeyDown={(e) => handleKeyDown(e, index)}
            onPaste={index === 0 ? handlePaste : undefined}
            className={cn(
              "w-12 h-14 text-center text-xl font-bold rounded-xl border transition-all duration-200 outline-hidden font-mono",
              val !== ""
                ? "bg-zinc-50 border-zinc-900 dark:bg-zinc-900/50 dark:border-zinc-100 text-zinc-900 dark:text-zinc-50 shadow-xs"
                : "bg-white border-zinc-200 dark:bg-zinc-900 dark:border-zinc-800 text-zinc-400 dark:text-zinc-500",
              "focus:border-zinc-900 focus:ring-4 focus:ring-zinc-900/5 dark:focus:border-zinc-100 dark:focus:ring-zinc-100/5",
              error && "border-red-500 ring-red-500/10 dark:border-red-400 dark:ring-red-400/10",
            )}
          />
        ))}
      </div>

      <div className="flex justify-between items-center mt-6 text-xs">
        <span className="text-zinc-400 dark:text-zinc-500">Didn't receive code?</span>
        <button
          onClick={triggerErrorShake}
          className="text-zinc-950 dark:text-zinc-50 font-semibold hover:underline"
        >
          Resend code
        </button>
      </div>
    </div>
  );
}

